{
  "id": "V040",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "회의에 사용할 고객 의견 경향 요약이라는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "의견 검토, 주제 정리·경향 분석, 근거 의견을 포함한 자료 작성이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "고객 의견의 반복 요구와 불편 주제가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "이번 주 고객 의견을 입력으로 명시하며, 주간 접수 의견 검토도 보존됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "경향을 뒷받침하는 의견을 포함한 회의용 요약 자료가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "개별 고객 답장과 제품 개선 효과 예측 제외가 BUSINESS 뷰에 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능이나 작업이 추가되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "서비스 기획팀의 업무 맥락이 BUSINESS 뷰에 보존되고, 다른 뷰도 역할을 변경하지 않음."
    }
  ],
  "issues": [],
  "permission_interpretation": "개별 고객에게 답장하거나 제품 개선 효과를 예측하는 작업은 제외됨. 답장이나 예측을 수행한다는 의미는 없음."
}
